FROM jsonb_to_recordset($vt$[{"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "en", "display_name": "Brinjal Arka Anand", "short_description": "Hybrid brinjal resistant to bacterial wilt, with green, medium long fruits and a yield of 55-60 t/ha.", "detailed_description": "Arka Anand is a hybrid brinjal released by ICAR-Indian Institute of Horticultural Research, Bengaluru. It comes from the cross IIHR-3 X IIHR-322. The crop duration is 145-150 days. The fruits are green in colour and medium long, and they have excellent cooking quality. The yield is 55-60 t/ha. It is recommended for Rajasthan, Gujarat, Haryana, Delhi, Madhya Pradesh, Maharashtra, Karnataka, Tamil Nadu and Kerala. It is resistant to bacterial wilt.", "local_synonyms": ["Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "hi", "display_name": "बैंगन अर्का आनंद", "short_description": "जीवाणु उकठा रोग के प्रति प्रतिरोधी संकर बैंगन, जिसके फल हरे और मध्यम लंबे हैं तथा उपज 55-60 t/ha है।", "detailed_description": "अर्का आनंद बैंगन की संकर किस्म है, जिसे ICAR-भारतीय बागवानी अनुसंधान संस्थान, बेंगलुरु ने जारी किया है। यह IIHR-3 X IIHR-322 के संकरण से बनी है। फसल अवधि 145-150 दिन है। फल हरे रंग के और मध्यम लंबे होते हैं, और पकाने के लिए इनकी गुणवत्ता उत्कृष्ट है। उपज 55-60 t/ha है। यह राजस्थान, गुजरात, हरियाणा, दिल्ली, मध्य प्रदेश, महाराष्ट्र, कर्नाटक, तमिलनाडु और केरल के लिए अनुशंसित है। यह जीवाणु उकठा रोग के प्रति प्रतिरोधी है।", "local_synonyms": ["बैंगन", "Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "mr", "display_name": "वांगे अर्का आनंद", "short_description": "जिवाणूजन्य मर रोगास प्रतिकारक संकरित वाण; फळे हिरवी, मध्यम लांब आणि उत्पादन 55-60 t/ha.", "detailed_description": "अर्का आनंद हा वांग्याचा संकरित वाण ICAR-भारतीय बागायती संशोधन संस्था, बेंगळुरू यांनी प्रसारित केला आहे. हा IIHR-3 X IIHR-322 या संकरातून तयार झाला आहे. पिकाचा कालावधी 145-150 दिवस आहे. फळे हिरव्या रंगाची व मध्यम लांब असून स्वयंपाकासाठी त्यांची प्रत उत्कृष्ट आहे. उत्पादन 55-60 t/ha मिळते. हा वाण राजस्थान, गुजरात, हरियाणा, दिल्ली, मध्य प्रदेश, महाराष्ट्र, कर्नाटक, तमिळनाडू व केरळसाठी शिफारस केलेला आहे. हा वाण जिवाणूजन्य मर रोगास प्रतिकारक आहे.", "local_synonyms": ["वांगे", "Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "pa", "display_name": "ਬੈਂਗਣ ਅਰਕਾ ਆਨੰਦ", "short_description": "ਬੈਕਟੀਰੀਅਲ ਉਖੇੜਾ ਰੋਗ ਦੀ ਰੋਧਕ ਹਾਈਬ੍ਰਿਡ ਕਿਸਮ; ਫਲ ਹਰੇ ਅਤੇ ਦਰਮਿਆਨੇ ਲੰਮੇ, ਝਾੜ 55-60 t/ha।", "detailed_description": "ਅਰਕਾ ਆਨੰਦ ਬੈਂਗਣ ਦੀ ਹਾਈਬ੍ਰਿਡ ਕਿਸਮ ਹੈ, ਜੋ ICAR-ਭਾਰਤੀ ਬਾਗਬਾਨੀ ਖੋਜ ਸੰਸਥਾ, ਬੰਗਲੁਰੂ ਵੱਲੋਂ ਜਾਰੀ ਕੀਤੀ ਗਈ ਹੈ। ਇਹ IIHR-3 X IIHR-322 ਦੇ ਕਰਾਸ ਤੋਂ ਬਣੀ ਹੈ। ਫ਼ਸਲ ਦਾ ਸਮਾਂ 145-150 ਦਿਨ ਹੈ। ਫਲ ਹਰੇ ਰੰਗ ਦੇ ਅਤੇ ਦਰਮਿਆਨੇ ਲੰਮੇ ਹੁੰਦੇ ਹਨ, ਅਤੇ ਪਕਾਉਣ ਲਈ ਇਨ੍ਹਾਂ ਦੀ ਗੁਣਵੱਤਾ ਉੱਤਮ ਹੈ। ਝਾੜ 55-60 t/ha ਹੈ। ਇਹ ਰਾਜਸਥਾਨ, ਗੁਜਰਾਤ, ਹਰਿਆਣਾ, ਦਿੱਲੀ, ਮੱਧ ਪ੍ਰਦੇਸ਼, ਮਹਾਰਾਸ਼ਟਰ, ਕਰਨਾਟਕ, ਤਾਮਿਲਨਾਡੂ ਅਤੇ ਕੇਰਲ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਗਈ ਹੈ। ਇਹ ਬੈਕਟੀਰੀਅਲ ਉਖੇੜਾ ਰੋਗ ਦੀ ਰੋਧਕ ਹੈ।", "local_synonyms": ["ਬੈਂਗਣ", "Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "gu", "display_name": "રીંગણ અર્કા આનંદ", "short_description": "બેક્ટેરિયલ સુકારા સામે પ્રતિકારક હાઇબ્રિડ જાત; ફળ લીલા અને મધ્યમ લાંબા, ઉત્પાદન 55-60 t/ha.", "detailed_description": "અર્કા આનંદ રીંગણની હાઇબ્રિડ જાત છે, જે ICAR-ભારતીય બાગાયત સંશોધન સંસ્થા, બેંગલુરુ દ્વારા બહાર પાડવામાં આવી છે. તે IIHR-3 X IIHR-322 ના સંકરણથી બનેલી છે. પાકનો સમયગાળો 145-150 દિવસ છે. ફળ લીલા રંગના અને મધ્યમ લાંબા હોય છે, અને રાંધવા માટે તેની ગુણવત્તા ઉત્તમ છે. ઉત્પાદન 55-60 t/ha છે. આ જાત રાજસ્થાન, ગુજરાત, હરિયાણા, દિલ્હી, મધ્ય પ્રદેશ, મહારાષ્ટ્ર, કર્ણાટક, તમિલનાડુ અને કેરળ માટે ભલામણ કરેલી છે. તે બેક્ટેરિયલ સુકારા સામે પ્રતિકારક છે.", "local_synonyms": ["રીંગણ", "Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "ta", "display_name": "கத்திரிக்காய் அர்கா ஆனந்த்", "short_description": "பாக்டீரியா வாடல் நோய்க்கு எதிர்ப்புத் திறன் கொண்ட வீரிய ஒட்டு ரகம்; பச்சை நிற, நடுத்தர நீளக் காய்கள், மகசூல் 55-60 t/ha.", "detailed_description": "அர்கா ஆனந்த் என்பது ICAR-இந்திய தோட்டக்கலை ஆராய்ச்சி நிறுவனம், பெங்களூரு வெளியிட்ட வீரிய ஒட்டு கத்திரி ரகம் ஆகும். இது IIHR-3 X IIHR-322 என்ற கலப்பிலிருந்து உருவானது. பயிர்க் காலம் 145-150 நாட்கள். காய்கள் பச்சை நிறத்திலும் நடுத்தர நீளத்திலும் இருக்கும்; அவற்றின் சமையல் தரம் மிகச் சிறந்தது. மகசூல் 55-60 t/ha. இது ராஜஸ்தான், குஜராத், ஹரியானா, டெல்லி, மத்தியப் பிரதேசம், மகாராஷ்டிரா, கர்நாடகா, தமிழ்நாடு மற்றும் கேரளாவுக்குப் பரிந்துரைக்கப்படுகிறது. இது பாக்டீரியா வாடல் நோய்க்கு எதிர்ப்புத் திறன் கொண்டது.", "local_synonyms": ["கத்திரிக்காய்", "Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "te", "display_name": "వంకాయ అర్కా ఆనంద్", "short_description": "బాక్టీరియా ఎండు తెగులుకు నిరోధక శక్తి గల హైబ్రిడ్ రకం; కాయలు ఆకుపచ్చగా, మధ్యస్థ పొడవుగా ఉంటాయి, దిగుబడి 55-60 t/ha.", "detailed_description": "అర్కా ఆనంద్ అనేది ICAR-భారతీయ ఉద్యాన పరిశోధన సంస్థ, బెంగళూరు విడుదల చేసిన వంకాయ హైబ్రిడ్ రకం. ఇది IIHR-3 X IIHR-322 సంకరణం నుండి వచ్చింది. పంట కాలం 145-150 రోజులు. కాయలు ఆకుపచ్చ రంగులో, మధ్యస్థ పొడవుగా ఉంటాయి; వంటకు వీటి నాణ్యత అత్యుత్తమం. దిగుబడి 55-60 t/ha. ఇది రాజస్థాన్, గుజరాత్, హర్యానా, ఢిల్లీ, మధ్యప్రదేశ్, మహారాష్ట్ర, కర్ణాటక, తమిళనాడు మరియు కేరళ రాష్ట్రాలకు సిఫార్సు చేయబడింది. ఇది బాక్టీరియా ఎండు తెగులుకు నిరోధక శక్తి కలిగి ఉంది.", "local_synonyms": ["వంకాయ", "Arka-Anand"]}, {"variety_id": "9e4de675-0cd3-4fa8-9f45-3d90454cb405", "language_code": "kn", "display_name": "ಬದನೆಕಾಯಿ ಅರ್ಕಾ ಆನಂದ್", "short_description": "ಬ್ಯಾಕ್ಟೀರಿಯಾ ಸೊರಗು ರೋಗಕ್ಕೆ ನಿರೋಧಕ ಹೈಬ್ರಿಡ್ ತಳಿ; ಕಾಯಿಗಳು ಹಸಿರು ಬಣ್ಣದ, ಮಧ್ಯಮ ಉದ್ದದವು, ಇಳುವರಿ 55-60 t/ha.", "detailed_description": "ಅರ್ಕಾ ಆನಂದ್ ಎಂಬುದು ICAR-ಭಾರತೀಯ ತೋಟಗಾರಿಕೆ ಸಂಶೋಧನಾ ಸಂಸ್ಥೆ, ಬೆಂಗಳೂರು ಬಿಡುಗಡೆ ಮಾಡಿದ ಬದನೆಯ ಹೈಬ್ರಿಡ್ ತಳಿ. ಇದು IIHR-3 X IIHR-322 ಸಂಕರಣದಿಂದ ಬಂದಿದೆ. ಬೆಳೆಯ ಅವಧಿ 145-150 ದಿನಗಳು. ಕಾಯಿಗಳು ಹಸಿರು ಬಣ್ಣದ, ಮಧ್ಯಮ ಉದ್ದದವಾಗಿದ್ದು, ಅಡುಗೆಗೆ ಅತ್ಯುತ್ತಮ ಗುಣಮಟ್ಟ ಹೊಂದಿವೆ. ಇಳುವರಿ 55-60 t/ha. ಇದನ್ನು ರಾಜಸ್ಥಾನ, ಗುಜರಾತ್, ಹರಿಯಾಣ, ದೆಹಲಿ, ಮಧ್ಯಪ್ರದೇಶ, ಮಹಾರಾಷ್ಟ್ರ, ಕರ್ನಾಟಕ, ತಮಿಳುನಾಡು ಮತ್ತು ಕೇರಳಕ್ಕೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ. ಇದು ಬ್ಯಾಕ್ಟೀರಿಯಾ ಸೊರಗು ರೋಗಕ್ಕೆ ನಿರೋಧಕವಾಗಿದೆ.", "local_synonyms": ["ಬದನೆಕಾಯಿ", "Arka-Anand"]}, {"variety_id": "a7ecbf7e-c2f1-464b-9382-b7ddf249749a", "language_code": "en", "display_name": "Brinjal Arka Navneeth", "short_description": "Hybrid brinjal with large, oval to oblong, deep purple shining fruits averaging 450 g, yielding 65-75 t/ha.", "detailed_description": "Arka Navneeth is a hybrid brinjal released by ICAR-Indian Institute of Horticultural Research, Bengaluru. It is an F1 hybrid between IIHR 22-1 and Supreme. The crop duration is 150-160 days. The flowers are purple and are borne singly. The fruits are large and oval to oblong, with deep purple shining skin and a green, thick and fleshy calyx; the average fruit weight is 450 g. The fruits are free from bitterness and have very good cooking quality. The yield is 65-75 t/ha. It is recommended for Himachal Pradesh, Jammu and Kashmir, the hills and Tarai region of Uttar Pradesh, West Bengal, Assam, Punjab, Bihar, Jharkhand, Rajasthan, Gujarat, Haryana, Delhi, Madhya Pradesh, Maharashtra, Karnataka, Tamil Nadu and Kerala.", "local_synonyms": ["Arka-Navneeth"]}, {"variety_id": "a7ecbf7e-c2f1-464b-9382-b7ddf249749a", "language_code": "hi", "display_name": "बैंगन अर्का नवनीत", "short_description": "बड़े, अंडाकार से लंबोतरे, गहरे बैंगनी चमकदार फलों (औसत 450 g) वाली संकर किस्म, उपज 65-75 t/ha।", "detailed_description": "अर्का नवनीत बैंगन की संकर किस्म है, जिसे ICAR-भारतीय बागवानी अनुसंधान संस्थान, बेंगलुरु ने जारी किया है। यह IIHR 22-1 और सुप्रीम के बीच का F1 संकर है। फसल अवधि 150-160 दिन है। फूल बैंगनी रंग के होते हैं और अकेले-अकेले लगते हैं। फल बड़े, अंडाकार से लंबोतरे होते हैं, छिलका गहरा बैंगनी और चमकदार होता है, और बाह्यदल (कैलिक्स) हरा, मोटा और गूदेदार होता है; फल का औसत वजन 450 g है। फलों में कड़वापन नहीं होता और पकाने के लिए इनकी गुणवत्ता बहुत अच्छी है। उपज 65-75 t/ha है। यह हिमाचल प्रदेश, जम्मू और कश्मीर, उत्तर प्रदेश के पहाड़ी और तराई क्षेत्र, पश्चिम बंगाल, असम, पंजाब, बिहार, झारखंड, राजस्थान, गुजरात, हरियाणा, दिल्ली, मध्य प्रदेश, महाराष्ट्र, कर्नाटक, तमिलनाडु और केरल के लिए अनुशंसित है।", "local_synonyms": ["बैंगन", "Arka-Navneeth"]}, {"variety_id": "a7ecbf7e-c2f1-464b-9382-b7ddf249749a", "language_code": "mr", "display_name": "वांगे अर्का नवनीत", "short_description": "मोठी, अंडाकृती ते लंबगोल, गडद जांभळी चकचकीत फळे (सरासरी 450 g) असलेला संकरित वाण; उत्पादन 65-75 t/ha.", "detailed_description": "अर्का नवनीत हा वांग्याचा संकरित वाण ICAR-भारतीय बागायती संशोधन संस्था, बेंगळुरू यांनी प्रसारित केला आहे. हा IIHR 22-1 आणि सुप्रीम यांच्यातील F1 संकर आहे. पिकाचा कालावधी 150-160 दिवस आहे. फुले जांभळ्या रंगाची असून ती एकेकटी येतात. फळे मोठी, अंडाकृती ते लंबगोल असून साल गडद जांभळी व चकचकीत असते, तर टोपी (कॅलिक्स) हिरवी, जाड व मांसल असते; फळाचे सरासरी वजन 450 g असते. फळांमध्ये कडूपणा नसतो आणि स्वयंपाकासाठी त्यांची प्रत खूप चांगली आहे. उत्पादन 65-75 t/ha मिळते. हा वाण हिमाचल प्रदेश, जम्मू आणि काश्मीर, उत्तर प्रदेशचा डोंगराळ व तराई भाग, पश्चिम बंगाल, आसाम, पंजाब, बिहार, झारखंड, राजस्थान, गुजरात, हरियाणा, दिल्ली, मध्य प्रदेश, महाराष्ट्र, कर्नाटक, तमिळनाडू व केरळसाठी शिफारस केलेला आहे.", "local_synonyms": ["वांगे", "Arka-Navneeth"]}, {"variety_id": "a7ecbf7e-c2f1-464b-9382-b7ddf249749a", "language_code": "pa", "display_name": "ਬੈਂਗਣ ਅਰਕਾ ਨਵਨੀਤ", "short_description": "ਵੱਡੇ, ਅੰਡਾਕਾਰ ਤੋਂ ਲੰਬੂਤਰੇ, ਗੂੜ੍ਹੇ ਜਾਮਣੀ ਚਮਕਦਾਰ ਫਲਾਂ (ਔਸਤ 450 g) ਵਾਲੀ ਹਾਈਬ੍ਰਿਡ ਕਿਸਮ, ਝਾੜ 65-75 t/ha।", "detailed_description": "ਅਰਕਾ ਨਵਨੀਤ ਬੈਂਗਣ ਦੀ ਹਾਈਬ੍ਰਿਡ ਕਿਸਮ ਹੈ, ਜੋ ICAR-ਭਾਰਤੀ ਬਾਗਬਾਨੀ ਖੋਜ ਸੰਸਥਾ, ਬੰਗਲੁਰੂ ਵੱਲੋਂ ਜਾਰੀ ਕੀਤੀ ਗਈ ਹੈ। ਇਹ IIHR 22-1 ਅਤੇ ਸੁਪਰੀਮ ਵਿਚਕਾਰ F1 ਹਾਈਬ੍ਰਿਡ ਹੈ। ਫ਼ਸਲ ਦਾ ਸਮਾਂ 150-160 ਦਿਨ ਹੈ। ਫੁੱਲ ਜਾਮਣੀ ਰੰਗ ਦੇ ਹੁੰਦੇ ਹਨ ਅਤੇ ਇਕੱਲੇ-ਇਕੱਲੇ ਲੱਗਦੇ ਹਨ। ਫਲ ਵੱਡੇ, ਅੰਡਾਕਾਰ ਤੋਂ ਲੰਬੂਤਰੇ ਹੁੰਦੇ ਹਨ, ਛਿਲਕਾ ਗੂੜ੍ਹਾ ਜਾਮਣੀ ਅਤੇ ਚਮਕਦਾਰ ਹੁੰਦਾ ਹੈ, ਅਤੇ ਕੈਲਿਕਸ (ਟੋਪੀ) ਹਰੀ, ਮੋਟੀ ਅਤੇ ਗੁੱਦੇਦਾਰ ਹੁੰਦੀ ਹੈ; ਫਲ ਦਾ ਔਸਤ ਭਾਰ 450 g ਹੈ। ਫਲਾਂ ਵਿੱਚ ਕੁੜੱਤਣ ਨਹੀਂ ਹੁੰਦੀ ਅਤੇ ਪਕਾਉਣ ਲਈ ਗੁਣਵੱਤਾ ਬਹੁਤ ਵਧੀਆ ਹੈ। ਝਾੜ 65-75 t/ha ਹੈ। ਇਹ ਹਿਮਾਚਲ ਪ੍ਰਦੇਸ਼, ਜੰਮੂ ਅਤੇ ਕਸ਼ਮੀਰ, ਉੱਤਰ ਪ੍ਰਦੇਸ਼ ਦੇ ਪਹਾੜੀ ਅਤੇ ਤਰਾਈ ਖੇਤਰ, ਪੱਛਮੀ ਬੰਗਾਲ, ਅਸਾਮ, ਪੰਜਾਬ, ਬਿਹਾਰ, ਝਾਰਖੰਡ, ਰਾਜਸਥਾਨ, ਗੁਜਰਾਤ, ਹਰਿਆਣਾ, ਦਿੱਲੀ, ਮੱਧ ਪ੍ਰਦੇਸ਼, ਮਹਾਰਾਸ਼ਟਰ, ਕਰਨਾਟਕ, ਤਾਮਿਲਨਾਡੂ ਅਤੇ ਕੇਰਲ ਲਈ ਸਿਫ਼ਾਰਸ਼ ਕੀਤੀ ਗਈ ਹੈ।", "local_synonyms": ["ਬੈਂਗਣ", "Arka-Navneeth"]}, {"variety_id": "a7ecbf7e-c2f1-464b-9382-b7ddf249749a", "language_code": "gu", "display_name": "રીંગણ અર્કા નવનીત", "short_description": "મોટા, અંડાકારથી લંબગોળ, ઘેરા જાંબલી ચળકતા ફળ (સરેરાશ 450 g) વાળી હાઇબ્રિડ જાત; ઉત્પાદન 65-75 t/ha.", "detailed_description": "અર્કા નવનીત રીંગણની હાઇબ્રિડ જાત છે, જે ICAR-ભારતીય બાગાયત સંશોધન સંસ્થા, બેંગલુરુ દ્વારા બહાર પાડવામાં આવી છે. તે IIHR 22-1 અને સુપ્રીમ વચ્ચેની F1 હાઇબ્રિડ છે. પાકનો સમયગાળો 150-160 દિવસ છે. ફૂલ જાંબલી રંગના હોય છે અને એકલા-એકલા આવે છે. ફળ મોટા, અંડાકારથી લંબગોળ હોય છે, છાલ ઘેરી જાંબલી અને ચળકતી હોય છે, અને ડીંટાની ટોપી (કેલિક્સ) લીલી, જાડી અને માંસલ હોય છે; ફળનું સરેરાશ વજન 450 g છે. ફળમાં કડવાશ હોતી નથી અને રાંધવા માટે ગુણવત્તા ખૂબ સારી છે. ઉત્પાદન 65-75 t/ha છે. આ જાત હિમાચલ પ્રદેશ, જમ્મુ અને કાશ્મીર, ઉત્તર પ્રદેશના પહાડી અને તરાઈ વિસ્તાર, પશ્ચિમ બંગાળ, આસામ, પંજાબ, બિહાર, ઝારખંડ, રાજસ્થાન, ગુજરાત, હરિયાણા, દિલ્હી, મધ્ય પ્રદેશ, મહારાષ્ટ્ર, કર્ણાટક, તમિલનાડુ અને કેરળ માટે ભલામણ કરેલી છે.", "local_synonyms": ["રીંગણ", "Arka-Navneeth"]}, {"variety_id": "a7ecbf7e-c2f1-464b-9382-b7ddf249749a", "language_code": "ta", "display_name": "கத்திரிக்காய் அர்கா நவநீத்", "short_description": "பெரிய, முட்டை வடிவம் முதல் நீள்வட்ட வடிவம் வரையிலான, அடர் ஊதா பளபளப்பான காய்கள் (சராசரி 450 g) கொண்ட வீரிய ஒட்டு ரகம்; மகசூல் 65-75 t/ha.", "detailed_description": "அர்கா நவநீத் என்பது ICAR-இந்திய தோட்டக்கலை ஆராய்ச்சி நிறுவனம், பெங்களூரு வெளியிட்ட வீரிய ஒட்டு கத்திரி ரகம் ஆகும். இது IIHR 22-1 மற்றும் சுப்ரீம் இடையிலான F1 வீரிய ஒட்டு ஆகும். பயிர்க் காலம் 150-160 நாட்கள். பூக்கள் ஊதா நிறத்தில் இருக்கும், அவை தனித்தனியாகப் பூக்கும். காய்கள் பெரியவை, முட்டை வடிவம் முதல் நீள்வட்ட வடிவம் வரை இருக்கும்; தோல் அடர் ஊதா நிறத்தில் பளபளப்பாக இருக்கும்; புல்லிவட்டம் பச்சையாகவும் தடிமனாகவும் சதைப்பற்றுடனும் இருக்கும்; ஒரு காயின் சராசரி எடை 450 g. காய்களில் கசப்பு இருக்காது, சமையல் தரம் மிகவும் நன்றாக இருக்கும். மகசூல் 65-75 t/ha. இ